  'Gerontological Nursing',
  'This course prepares nursing students to care for older adults across home, community, acute, rehabilitation, assisted living, long-term care, and palliative settings. Students learn normal aging, geriatric syndromes, cognition, medication safety, mobility, function, nutrition, skin integrity, chronic disease, palliative care, ethics, caregiver partnership, transitions, and evidence-based age-friendly nursing practice.',
  $gerjson${"slug": "gerontological-nursing", "title": "Gerontological Nursing", "description": "This course prepares nursing students to care for older adults across home, community, acute, rehabilitation, assisted living, long-term care, and palliative settings. Students learn normal aging, geriatric syndromes, cognition, medication safety, mobility, function, nutrition, skin integrity, chronic disease, palliative care, ethics, caregiver partnership, transitions, and evidence-based age-friendly nursing practice.", "topics": [{"id": "8aefe3e1-e62b-4871-b5dc-c44b7d4dc4b3", "type": "topic", "title": "Foundations of gerontological nursing, aging theories, and age-friendly care", "description": "Frame older-adult nursing around normal aging, personhood, dignity, ageism, equity, and strengths-based care.", "children": [{"id": "37c3b6b8-5138-4d8d-b7da-81fc91ef346f", "type": "subtopic", "title": "Theories and meanings of aging", "description": "Students learn that aging is biologic, psychological, social, cultural, and spiritual, not simply decline.", "children": [{"id": "c3369f6d-535c-40e4-b03a-57d5b4978d1a", "type": "concept", "title": "Biologic, psychosocial, and developmental theories"}, {"id": "8507142e-f340-4ab4-8a16-f38f90e03616", "type": "concept", "title": "Successful aging, healthy aging, and resilience"}, {"id": "4c287cc9-dd2f-464d-ab03-c574ded1ac99", "type": "concept", "title": "Life course, cohort effects, and social context"}]}, {"id": "9c036cf4-a652-4838-afa4-4d05757d4e2d", "type": "subtopic", "title": "Age-friendly nursing values", "description": "This subtopic centers dignity, autonomy, respect, and what matters most to the older adult.", "children": [{"id": "e5bc8160-5e18-4a6b-b4f3-12626ca607ad", "type": "concept", "title": "Person-centered care"}, {"id": "3bb568e9-afce-4d0d-9b74-37cf32e33daa", "type": "concept", "title": "Ageism and implicit bias"}, {"id": "94c4f39c-c472-4f49-bfd1-4c1c5ceaffea", "type": "concept", "title": "Cultural humility, health equity, and trauma-informed care"}]}, {"id": "d0d83485-d14b-4e74-b4a5-9c9616b41f26", "type": "subtopic", "title": "Role of the gerontological nurse", "description": "Students see how nurses coordinate complex care while protecting function and quality of life.", "children": [{"id": "197bdb1f-375a-4995-a774-601eb91972c5", "type": "concept", "title": "Assessment, education, advocacy, and coordination"}, {"id": "6d29ddf7-2252-4ce9-849e-fa762b263412", "type": "concept", "title": "Family and caregiver partnership"}, {"id": "94bca33e-5e41-4927-bf4a-8f571ad47666", "type": "concept", "title": "Scope, delegation, and interprofessional collaboration"}]}]}, {"id": "4c2a2227-ea89-44d4-a39e-2b026e0e69b1", "type": "topic", "title": "Physiologic aging and comprehensive geriatric assessment", "description": "Distinguish expected age-related changes from disease and build a structured whole-person assessment.", "children": [{"id": "ea0d9b3d-f2b0-4831-b774-a8f70b49deec", "type": "subtopic", "title": "Normal aging versus disease", "description": "Students learn to avoid both overmedicalizing normal change and dismissing treatable disease as aging.", "children": [{"id": "3abcf3e8-f9ed-4fa6-8f5f-799905812bb7", "type": "concept", "title": "Cardiovascular, pulmonary, renal, endocrine, and immune changes"}, {"id": "39cacc0d-b5d6-4f19-a3aa-3b4084a27454", "type": "concept", "title": "Musculoskeletal, neurologic, sensory, and integumentary changes"}, {"id": "88a36442-f3d8-4b2a-9b71-bdb39b8261e5", "type": "concept", "title": "Atypical presentation of illness"}]}, {"id": "f7be3b17-c640-4b27-a7df-59dd09086051", "type": "subtopic", "title": "Comprehensive geriatric assessment", "description": "This subtopic introduces a structured, multidomain assessment that captures risk, function, cognition, mood, and goals.", "children": [{"id": "859c5be0-90e8-4a51-bf5c-0ba8743e82f4", "type": "concept", "title": "Functional status and ADLs/IADLs"}, {"id": "195a3d10-bd1f-4c60-81eb-f7b31e606c7c", "type": "concept", "title": "Cognition, mood, mobility, nutrition, medications, and social support"}, {"id": "b3127f67-3f3a-49ff-a6cc-568bf2dc82b2", "type": "concept", "title": "Goals of care and what matters most"}]}, {"id": "4711dd0b-32c3-4d66-bcd1-00678d9cce75", "type": "subtopic", "title": "Risk stratification and clinical judgment", "description": "Students connect assessment findings to nursing priorities and escalation decisions.", "children": [{"id": "b3925d36-667a-4a37-85b4-d858de0cc3fb", "type": "concept", "title": "Red flags and urgent changes"}, {"id": "5e835bc7-1bef-4f57-ae2d-348cd41c0e87", "type": "concept", "title": "Baseline versus acute deviation"}, {"id": "7d6ca8de-a662-4622-9d85-1fff330e79d6", "type": "concept", "title": "Prioritization and documentation"}]}]}, {"id": "edcfc1fe-c51f-49b7-8a4a-63b757998353", "type": "topic", "title": "Frailty, multimorbidity, geriatric syndromes, and chronic illness", "description": "Recognize interacting conditions that threaten function, resilience, and quality of life.", "children": [{"id": "be9462eb-52d4-443e-a63a-7625f132d984", "type": "subtopic", "title": "Frailty and physiologic reserve", "description": "Frailty helps students understand why small stressors can cause major functional decline.", "children": [{"id": "67689f23-9bf1-47a6-97d2-c5222f3538e2", "type": "concept", "title": "Frailty phenotype and deficit accumulation"}, {"id": "d09043ff-32d2-4c1f-b091-229785c0bcb4", "type": "concept", "title": "Sarcopenia and unintentional weight loss"}, {"id": "934be573-8091-4625-9006-b91e14d1b885", "type": "concept", "title": "Resilience, reserve, and recovery trajectory"}]}, {"id": "6102a171-3149-4acf-ae12-f0185d9c58c9", "type": "subtopic", "title": "Multimorbidity and geriatric syndromes", "description": "This subtopic highlights conditions that interact across body systems and care settings.", "children": [{"id": "98c9fde2-f246-4b4f-9516-181300e4b61c", "type": "concept", "title": "Falls, delirium, incontinence, pressure injuries, malnutrition, and pain"}, {"id": "d085ef51-a1a7-4164-b492-f41a0d87a80e", "type": "concept", "title": "Diabetes, heart failure, COPD, CKD, arthritis, and osteoporosis"}, {"id": "aa5b7ea3-ad4d-4303-9a48-b663e1d610ee", "type": "concept", "title": "Atypical disease presentation and competing priorities"}]}, {"id": "bae6dcfb-24f8-4ff7-851b-a4b0145a3044", "type": "subtopic", "title": "Nursing care planning for complexity", "description": "Students learn to move from single-disease thinking to coordinated, goal-concordant care.", "children": [{"id": "5094c3f1-f68c-4095-9465-49bec29a630c", "type": "concept", "title": "Problem clustering and risk mapping"}, {"id": "e5a89688-1f82-4f03-80e4-464ce4376c64", "type": "concept", "title": "Functional goals and symptom burden"}, {"id": "9f1a9d21-af02-4a90-97ef-1592a21e76f6", "type": "concept", "title": "Care coordination and self-management support"}]}]}, {"id": "80164a9c-a8ab-4b73-adef-9207427c007d", "type": "topic", "title": "Cognitive and mental health changes: delirium, dementia, depression, and communication", "description": "Assess cognition and mood while supporting safety, identity, communication, and caregiver partnership.", "children": [{"id": "645b6e97-ddc5-45fe-8a28-8036d71a65a6", "type": "subtopic", "title": "Delirium recognition and prevention", "description": "Students learn to identify acute cognitive change quickly because delirium is common, dangerous, and often reversible.", "children": [{"id": "c42cb9c0-72c0-4cb9-bc05-680b09b2e281", "type": "concept", "title": "CAM-style screening concepts"}, {"id": "23192158-7910-4590-9be5-361d70bf864a", "type": "concept", "title": "Medication, infection, dehydration, pain, sleep, and sensory triggers"}, {"id": "16bd26bb-6731-41bd-b805-41f97300cd42", "type": "concept", "title": "Nonpharmacologic prevention and safety"}]}, {"id": "6faf9cfb-d051-48d2-b55c-ff8cd70832fa", "type": "subtopic", "title": "Dementia and cognitive impairment", "description": "This subtopic focuses on progressive cognitive change while preserving personhood and function.", "children": [{"id": "978879d3-d4e6-4afb-a263-ad77115f3e4e", "type": "concept", "title": "Alzheimer's disease and other dementias"}, {"id": "a87b00a7-fcbb-4cc3-9791-4e5813c92fb8", "type": "concept", "title": "Behavioral and psychological symptoms"}, {"id": "1a2be553-2f7d-49c9-92c4-67bdf95598d7", "type": "concept", "title": "Communication, routines, safety, and caregiver education"}]}, {"id": "7f4738d0-96b5-4e01-8e34-a72302e6348c", "type": "subtopic", "title": "Depression, loneliness, and communication", "description": "Students learn to assess mood and social connection without assuming sadness is a normal part of aging.", "children": [{"id": "da8244a8-ae26-41f2-99b6-f89b0ffb1492", "type": "concept", "title": "Depression screening and suicide risk awareness"}, {"id": "1e91d7e0-9bdf-4b15-a444-86b462338f99", "type": "concept", "title": "Grief, isolation, and social determinants"}, {"id": "d9683f99-d8a1-4bd5-98f8-a06a2df7013c", "type": "concept", "title": "Hearing, vision, aphasia, and health literacy adaptations"}]}]}, {"id": "dbb7d0c9-a72c-49c9-82da-c8f0321e84fb", "type": "topic", "title": "Polypharmacy, medication safety, and prescribing risk in older adults", "description": "Apply geriatric medication principles, Beers Criteria awareness, reconciliation, and deprescribing thinking.", "children": [{"id": "07bd369a-febc-4452-8e7d-b273dbc5eb41", "type": "subtopic", "title": "Age-related pharmacology", "description": "Students learn why older adults often need different medication risk assessment than younger adults.", "children": [{"id": "4f6865b1-856a-4ea2-8473-8390cb45129c", "type": "concept", "title": "Pharmacokinetics and pharmacodynamics"}, {"id": "2bcb4681-de9d-483c-9c08-a21df86cc3a0", "type": "concept", "title": "Renal/hepatic function and body composition changes"}, {"id": "c5b8138c-f073-4dd1-a85f-e8e2933e4ce3", "type": "concept", "title": "Adverse drug events and drug-disease interactions"}]}, {"id": "0bf61736-dea6-48ac-a704-13fbf256191d", "type": "subtopic", "title": "Medication reconciliation and Beers Criteria awareness", "description": "This subtopic teaches students to identify potentially inappropriate medications and communicate concerns safely.", "children": [{"id": "7e75a107-b6ae-4fe7-b7a1-c6d1ca9af35f", "type": "concept", "title": "Medication history and reconciliation"}, {"id": "dc495d6d-8c1a-43f3-9ac8-a0c912ae7cc3", "type": "concept", "title": "2023 AGS Beers Criteria categories"}, {"id": "19f68f39-54cd-498e-867a-030711c0cbf3", "type": "concept", "title": "High-risk medications, anticholinergic burden, sedatives, and anticoagulants"}]}, {"id": "ce03203f-70a8-4c34-a297-e241cdc29c02", "type": "subtopic", "title": "Deprescribing and adherence support", "description": "Students learn to support safer medication use through shared decision-making and practical systems.", "children": [{"id": "8f830f65-43c3-412d-b3ce-1ad6af6e71c3", "type": "concept", "title": "Deprescribing principles"}, {"id": "f1f1dded-5f0e-41d5-a49b-b8256dd293cf", "type": "concept", "title": "Teach-back, pill organization, affordability, and caregiver role"}, {"id": "20684b0f-1cc2-4b17-8b3a-970c9b77bc1e", "type": "concept", "title": "Monitoring, follow-up, and escalation"}]}]}, {"id": "a8a9ed09-d112-4d60-af52-50b7f5ca6549", "type": "topic", "title": "Falls, mobility, function, rehabilitation, and environmental safety", "description": "Prevent injury and preserve independence through mobility assessment, STEADI-style fall prevention, and safe environments.", "children": [{"id": "8be16107-85f5-4904-b80e-2af98030839b", "type": "subtopic", "title": "Fall risk screening and prevention", "description": "Students learn to treat falls as preventable sentinel events rather than inevitable aging outcomes.", "children": [{"id": "5a1db347-f3f9-4798-911c-86a13a18792d", "type": "concept", "title": "Fall history and risk factors"}, {"id": "ba1ee27d-4fad-4142-aacb-9f900868fda2", "type": "concept", "title": "CDC STEADI-style screening and intervention concepts"}, {"id": "b6646fb4-9162-4eb0-aac4-6971c1c84020", "type": "concept", "title": "Vision, footwear, orthostasis, medication, and home hazards"}]}, {"id": "a358152b-b586-4d33-b25a-1ab6b951d164", "type": "subtopic", "title": "Mobility, gait, and assistive devices", "description": "This subtopic links movement assessment to independence and injury prevention.", "children": [{"id": "25005881-d296-4250-a624-e836d9c2d8fb", "type": "concept", "title": "Gait, balance, strength, and transfers"}, {"id": "67791a31-0b16-41c4-b6c2-a2feffcf5630", "type": "concept", "title": "Canes, walkers, wheelchairs, and safe use"}, {"id": "20f1e3fe-d72f-44b5-8197-06ef1d1e5a1d", "type": "concept", "title": "Exercise, strength, power, and endurance"}]}, {"id": "bddf04f3-ba77-4cc3-beb7-e4b04a9ab735", "type": "subtopic", "title": "Function and rehabilitation goals", "description": "Students learn to preserve ADLs, participation, and meaningful routines.", "children": [{"id": "d894c454-faee-4d7d-831c-d12e1367cf17", "type": "concept", "title": "ADLs/IADLs and functional measures"}, {"id": "8ed191a5-3ecc-4535-a351-e45b2f0b2dea", "type": "concept", "title": "PT/OT collaboration"}, {"id": "6e37ce0f-aaa6-40ce-8440-6c62bd663eb6", "type": "concept", "title": "Discharge planning and community resources"}]}]}, {"id": "237c86cd-52c2-4cbc-976a-a8279a6b2cbe", "type": "topic", "title": "Skin integrity, nutrition, hydration, continence, and sensory changes", "description": "Manage common functional vulnerabilities that drive morbidity, hospitalization, and loss of independence.", "children": [{"id": "bbce31d6-9204-483d-be65-aa3d5c9ac55e", "type": "subtopic", "title": "Skin integrity and pressure injury prevention", "description": "Students learn to prevent tissue injury through assessment, mobility, nutrition, surfaces, and moisture control.", "children": [{"id": "1daa1df2-d39d-4871-bfd7-2d3fe623c2ec", "type": "concept", "title": "Risk assessment and staging concepts"}, {"id": "f979ed88-7de1-4f5c-9b59-f106419ee7ca", "type": "concept", "title": "Repositioning, support surfaces, and offloading"}, {"id": "ef0f4c44-3887-4730-8f3e-224165eb4296", "type": "concept", "title": "Wound observation and escalation"}]}, {"id": "38e1d050-4e60-42e9-bdd2-8811fe69f5d0", "type": "subtopic", "title": "Nutrition and hydration", "description": "This subtopic addresses high-impact, often underrecognized drivers of frailty and poor recovery.", "children": [{"id": "cc8d4283-b057-4426-a4fe-c11e1091ebd0", "type": "concept", "title": "Malnutrition screening"}, {"id": "0fc9cd9b-0fa3-4abf-9151-c941458bcbc9", "type": "concept", "title": "Dysphagia, dentition, appetite, and food access"}, {"id": "ad606dc4-bf5d-44a0-b021-c491d0ecee68", "type": "concept", "title": "Dehydration, electrolytes, and fluid balance"}]}, {"id": "f96da166-fbf9-4015-b1eb-9137ca989d79", "type": "subtopic", "title": "Continence and sensory function", "description": "Students learn practical, dignity-preserving approaches to common functional problems.", "children": [{"id": "6e18ecab-caf0-4cfa-90dc-723124f2f22a", "type": "concept", "title": "Urinary incontinence and toileting plans"}, {"id": "ef2f2849-19f8-4d9b-9131-8ef7c6c33cf5", "type": "concept", "title": "Constipation and bowel regimens"}, {"id": "eae99d20-5bc3-4d8a-8a35-f52c3d6f4047", "type": "concept", "title": "Vision, hearing, low vision, and communication adaptations"}]}]}, {"id": "173f7ea2-245f-4a6c-b2ac-06c0546f17cc", "type": "topic", "title": "Chronic disease management and health promotion in later life", "description": "Support self-management, prevention, screening, immunization, and behavior change for older adults with complex needs.", "children": [{"id": "cc14f1c8-500d-49c6-9c50-bda6ed11d0d1", "type": "subtopic", "title": "Older-adult chronic disease priorities", "description": "Students learn to manage chronic illness in the context of goals, function, comorbidity, and treatment burden.", "children": [{